import {Form as Material} from "./1Adding Interactivity/4UpdatingObjects"
import Root from "./1Adding Interactivity/4UpdatingObjects"
import Sub from "./subReLearn"
import "./ReLearn.css"
import { useState } from "react"

export default function () {
  const [obj, setObj] = useState({nest:{anjas:"ester egg"}})
  return (
    <>
    <input value={obj.inputF} onInput={(e) => {setObj({...obj, inputF: e.target.value})}}/> <br/>
    <input value={obj.inputL} onInput={(e) => {setObj({...obj, nest:{...obj.nest, inputL: e.target.value}})}} style={{}}/>
    <p>{obj.inputF}</p>
    <p>{obj.nest.inputL}</p>
    {obj.nest.anjas}
    </>
  );
}



// http://localhost:3000
